package com.mantou.salesdialer.contacts;
import android.app.*;import android.os.Bundle;import android.text.InputType;import android.util.AtomicFile;import android.widget.*;
import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
import com.mantou.salesdialer.contacts.ContactTaskModel.*;import com.mantou.salesdialer.contacts.SyntheticAttemptModel.Snapshot;import com.mantou.salesdialer.contacts.SyntheticWorkspaceSession.*;
/** User-operable local synthetic workspace. Intent extras never provide data, clock or identity. */
public final class SyntheticWorkspaceActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private SyntheticWorkspaceSession session;private View current;private String selectedId="",message="正在读取工作区……";private boolean busy=true,rendering,window,clockReady;private int generation;
 private TextView summary,notice;private Spinner contacts;private final Map<String,Button> buttons=new LinkedHashMap<>();private final String sessionId=UUID.randomUUID().toString();
 private interface Action{void run(View seen,Row row)throws Exception;}
 private Row selected(){if(current==null)return null;return current.contacts.stream().filter(r->r.contact.id.equals(selectedId)).findFirst().orElse(null);}
 private Row required(Row row){if(row==null)throw new IllegalStateException("SELECT_CONTACT");return row;}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);if(saved!=null)selectedId=saved.getString("selected","");
  LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);int pad=(int)(16*getResources().getDisplayMetrics().density);body.setPadding(pad,pad,pad,pad);ScrollView scroll=new ScrollView(this);scroll.addView(body);setContentView(scroll);
  TextView title=new TextView(this);title.setTextSize(21);title.setText("合成任务工作区");body.addView(title);TextView hint=new TextView(this);hint.setText("本机练习身份，仅SIM合成联系人，不拨电话。\n可安排单次自动模拟；仅记录请求，不拨电话。");body.addView(hint);
  summary=new TextView(this);summary.setPadding(0,pad/2,0,pad/2);body.addView(summary);contacts=new Spinner(this);contacts.setContentDescription("选择合成联系人");body.addView(contacts);contacts.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int index,long id){if(!rendering&&current!=null&&index<current.contacts.size()){selectedId=current.contacts.get(index).contact.id;controls();}}});
  row(body,"导入合成联系人",(v,r)->importDialog(),"查看工作区历史",(v,r)->history(v));
  row(body,"安排模拟时间",(v,r)->scheduleDialog(v,required(r)),"执行当前模拟计划",(v,r)->submit("EXECUTE",(seen,selected)->session.execute(seen.plan.version)));
  row(body,"立即模拟所选",(v,r)->submit("IMMEDIATE",(seen,selected)->session.immediate(required(selected),seen.plan.version)),"暂停计划",(v,r)->submit("PAUSE",(seen,selected)->session.pause(seen.plan.version)));
  row(body,"联系人操作",(v,r)->contactDialog(v,required(r)),"刷新工作区",(v,r)->submit("REFRESH_VIEW",(seen,selected)->{}));
  row(body,"模拟结果：未接",(v,r)->submit("RESULT_NO_ANSWER",(seen,selected)->session.result(seen.pending(),"NO_ANSWER")),"模拟结果：完成",(v,r)->submit("RESULT_COMPLETED",(seen,selected)->session.result(seen.pending(),"COMPLETED")));
  row(body,"结果仍未知",(v,r)->submit("RESULT_UNKNOWN",(seen,selected)->session.result(seen.pending(),"UNKNOWN")),"明确关闭未知占用",(v,r)->closeDialog(v));
  row(body,"30秒后自动模拟所选",(v,r)->submit("AUTO_30",(seen,selected)->session.automaticInThirtySeconds(required(selected),seen.plan.version)),"刷新定时结果",(v,r)->submit("TIMER_REFRESH",(seen,selected)->{}));
  notice=new TextView(this);notice.setPadding(0,pad/2,0,0);body.addView(notice);controls();
  worker.execute(()->{synchronized(WorkspaceTimerCoordinator.LOCK){try{session=new SyntheticWorkspaceSession(getApplicationContext());publish(session.view(),"OPEN","", "工作区已读取。重新进入会暂停旧计划，需明确重新安排。");}catch(Exception e){fatal(e);}}});
 }
 private void row(LinearLayout parent,String first,Action a,String second,Action b){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);add(row,first,a);add(row,second,b);parent.addView(row);}
 private void add(LinearLayout row,String text,Action action){Button button=new Button(this);button.setText(text);row.addView(button,new LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1));buttons.put(text,button);button.setOnClickListener(v->{if(busy||current==null)return;try{action.run(current,selected());}catch(Exception e){message=human(e.getMessage());controls();}});}
 private void submit(String action,Action work){View seen=current;Row chosen=selected();if(busy||seen==null)return;submitSeen(action,seen,chosen,work);}
 private void submitSeen(String action,View seen,Row chosen,Action work){if(busy)return;busy=true;controls();worker.execute(()->{synchronized(WorkspaceTimerCoordinator.LOCK){String error="",result=success(action);try{work.run(seen,chosen);if(action.equals("IMPORT"))result=session.importSummary();}catch(Exception e){error=String.valueOf(e.getMessage());result=human(error);}try{publish(session.view(),action,error,result);}catch(Exception e){fatal(e);}}});}
 private void publish(View view,String action,String error,String text){window=session.inWindow();clockReady=session.clockReady();int next=++generation;try{JSONObject report=new JSONObject().put("source","SYNTHETIC_WORKSPACE_UI").put("ready",true).put("sessionId",sessionId).put("generation",next).put("action",action).put("errorCode",error).put("realCallsEnabled",false).put("productionAuthenticated",false).put("actualPhoneCalls",0).put("inWindow",window).put("clockReady",clockReady);
   var c=view.counters;report.put("counters",new JSONObject().put("contacts",c.contacts).put("attempts",c.attempts).put("distinctTargets",c.distinctTargets).put("apiReceipts",c.apiReceipts).put("pending",c.pending).put("manualKnown",c.manualKnown).put("closedUnknown",c.closedUnknown));report.put("plan",new JSONObject().put("version",view.plan.version).put("paused",view.plan.paused).put("taskId",view.plan.taskId).put("dueAt",view.plan.dueAt));JSONArray rows=new JSONArray();for(Row r:view.contacts)rows.put(new JSONObject().put("id",r.contact.id).put("label",r.label).put("revision",r.contact.revision).put("draftRevision",r.task.contactRevision).put("qualification",r.contact.qualification.name()).put("refused",r.contact.refused).put("eligible",r.eligible()));report.put("contacts",rows);JSONArray attempts=new JSONArray();for(Snapshot a:view.attempts)attempts.put(new JSONObject().put("id",a.id).put("label",SyntheticWorkspaceModel.label(a.targetKey)).put("state",a.state).put("manualResult",a.manualResult).put("simulatedApiReceipt",a.simulatedApiReceipt).put("unknownClosed",a.unknownClosed).put("outgoingConfirmed",JSONObject.NULL).put("connectedConfirmed",JSONObject.NULL));report.put("attempts",attempts);writeReport(report);
  }catch(Exception e){android.util.Log.w("SyntheticWorkspace","Diagnostic report unavailable");}
  runOnUiThread(()->{if(isFinishing()||isDestroyed())return;current=view;busy=false;message=text;render();});
 }
 private void writeReport(JSONObject r)throws Exception{AtomicFile file=new AtomicFile(new File(getFilesDir(),"synthetic-workspace-status.json"));FileOutputStream out=null;try{out=file.startWrite();out.write(r.toString().getBytes(StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}
 private void fatal(Exception error){try{writeReport(new JSONObject().put("source","SYNTHETIC_WORKSPACE_UI").put("ready",false).put("errorCode",String.valueOf(error.getMessage())).put("actualPhoneCalls",0));}catch(Exception ignored){}runOnUiThread(()->{message="工作区读取失败，已停止。请保留数据，不要清库重试。";busy=true;controls();});}
 private void render(){rendering=true;List<String> labels=new ArrayList<>();int index=0;for(int i=0;i<current.contacts.size();i++){Row r=current.contacts.get(i);labels.add(r.label+(r.contact.refused?" · 拒绝联系":r.contact.qualification!=Qualification.CONFIRMED?" · 合成资格未知":!r.eligible()?" · 草稿过期":" · 可安排"));if(r.contact.id.equals(selectedId))index=i;}if(!current.contacts.isEmpty())selectedId=current.contacts.get(index).contact.id;contacts.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));if(!labels.isEmpty())contacts.setSelection(index,false);rendering=false;controls();}
 private void controls(){for(Button b:buttons.values())b.setEnabled(!busy&&current!=null);contacts.setEnabled(!busy&&current!=null&&!current.contacts.isEmpty());if(current==null){summary.setText("正在读取独立合成工作区");if(notice!=null)notice.setText(message);return;}
  var c=current.counters;Row row=selected();boolean canPlan=!busy&&row!=null&&row.eligible()&&c.pending==0;buttons.get("安排模拟时间").setEnabled(canPlan);buttons.get("30秒后自动模拟所选").setEnabled(canPlan&&window&&clockReady);buttons.get("立即模拟所选").setEnabled(canPlan&&window&&clockReady);buttons.get("执行当前模拟计划").setEnabled(!busy&&!current.plan.paused&&c.pending==0&&clockReady);buttons.get("联系人操作").setEnabled(!busy&&row!=null);for(String label:List.of("模拟结果：未接","模拟结果：完成","结果仍未知"))buttons.get(label).setEnabled(!busy&&c.pending>0);Snapshot pending=current.pending();buttons.get("明确关闭未知占用").setEnabled(!busy&&pending!=null&&pending.manualResult.equals("UNKNOWN"));
  String plan=current.plan.paused?"已暂停/已消费，需重新安排":"已安排 "+SyntheticWorkspaceModel.formatTime(current.plan.dueAt)+" 北京时间（单次自动模拟）";String target="";if(!current.plan.paused)target=current.contacts.stream().filter(r->r.task.id.equals(current.plan.taskId)).map(r->r.label+" · ").findFirst().orElse("");summary.setText("联系人 "+c.contacts+" · 已尝试目标 "+c.distinctTargets+"\n模拟尝试 "+c.attempts+" · 模拟API回执 "+c.apiReceipts+" · 待核对 "+c.pending+"\n人工明确结果 "+c.manualKnown+" · 未知关闭 "+c.closedUnknown+"\n计划版本 "+current.plan.version+" · "+target+plan+"\n本工作区真实呼叫 0；实际呼出/接通证据未知");
  String readiness=window?"":"\n当前不在北京时间工作日09:00–18:00，可编辑未来计划。";if(!clockReady)readiness+="\n无法确认设备启动代次，暂不模拟提交。";if(notice!=null)notice.setText((busy?"正在处理……":message)+readiness+(pending==null?"":"\n待核对："+SyntheticWorkspaceModel.label(pending.targetKey)+"，不会自动重放。"));
 }
 private EditText input(String value,boolean multiline){EditText input=new EditText(this);input.setText(value);input.setSelectAllOnFocus(true);input.setInputType(InputType.TYPE_CLASS_TEXT|(multiline?InputType.TYPE_TEXT_FLAG_MULTI_LINE:0));if(multiline)input.setMinLines(3);return input;}
 private void importDialog(){EditText input=input("",true);input.setHint("SIM-001\nSIM-002");new AlertDialog.Builder(this).setTitle("导入合成联系人").setMessage("每行SIM-三位数字；仅合成ID，不接受电话号码。整批校验，重复保留原记录。每批最多200行。").setView(input).setNegativeButton("取消",null).setPositiveButton("导入",(d,w)->{String text=input.getText().toString();submit("IMPORT",(v,r)->session.importIds(text));}).show();}
 private void scheduleDialog(View seen,Row row){ZonedDateTime suggested=ZonedDateTime.now(ZoneOffset.ofHours(8)).plusMinutes(5).withSecond(0).withNano(0);while(suggested.getDayOfWeek().getValue()>5||suggested.getHour()>=18||suggested.getHour()<9){suggested=suggested.getHour()<9?suggested.withHour(9).withMinute(0):suggested.plusDays(1).withHour(9).withMinute(0);}EditText input=input(SyntheticWorkspaceModel.formatTime(suggested.toInstant().toEpochMilli()),false);new AlertDialog.Builder(this).setTitle("安排模拟时间").setMessage(row.label+" · 北京时间 yyyy-MM-dd HH:mm\n将安排一次自动模拟；重新进入工作区会暂停旧计划。").setView(input).setNegativeButton("取消",null).setPositiveButton("保存计划",(d,w)->{String text=input.getText().toString();submitSeen("PLAN",seen,row,(v,r)->session.arrangeAutomatic(r,v.plan.version,text));}).show();}
 private void contactDialog(View seen,Row row){String[] labels={"合成资格设为未知","合成资格设为确认","拒绝联系","刷新所选草稿"};new AlertDialog.Builder(this).setTitle(row.label+" · 联系人操作").setItems(labels,(d,index)->submitSeen("CONTACT_"+index,seen,row,(v,r)->{switch(index){case 0:session.qualify(r,Qualification.UNKNOWN);break;case 1:session.qualify(r,Qualification.CONFIRMED);break;case 2:session.refuse(r);break;default:session.refresh(r);}})).setNegativeButton("取消",null).show();}
 private void closeDialog(View seen){Snapshot pending=seen.pending();if(pending==null)return;CheckBox confirmed=new CheckBox(this);confirmed.setText("我确认合成任务没有活动或待处理通话");AlertDialog dialog=new AlertDialog.Builder(this).setTitle("明确关闭未知占用").setMessage("仅合成任务，不检查手机真实通话。关闭后历史结果仍未知，原尝试不会重放；下一次须新计划。").setView(confirmed).setNegativeButton("取消",null).setPositiveButton("确认关闭",(d,w)->submitSeen("CLOSE_UNKNOWN",seen,selected(),(v,r)->session.closeUnknown(pending,confirmed.isChecked()))).create();dialog.setOnShowListener(d->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);confirmed.setOnCheckedChangeListener((b,checked)->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(checked));});dialog.show();}
 private void history(View view){StringBuilder text=new StringBuilder();for(Snapshot a:view.attempts)text.append(SyntheticWorkspaceModel.label(a.targetKey)).append(" · 计划").append(a.planVersion).append(" · ").append(a.id.substring(a.id.length()-8)).append("\n模拟API回执：").append(a.simulatedApiReceipt?"有":"无").append("；人工结果：").append(a.manualResult.isEmpty()?"待核对":a.manualResult).append(a.unknownClosed?"（未知占用已明确关闭）":"").append("\n实际呼出/接通：未知\n\n");TextView history=new TextView(this);history.setText(text.length()==0?"尚无模拟尝试":text.toString());history.setPadding(24,16,24,16);ScrollView scroll=new ScrollView(this);scroll.addView(history);new AlertDialog.Builder(this).setTitle("工作区历史（均为合成）").setView(scroll).setPositiveButton("关闭",null).show();}
 private static String success(String action){switch(action){case "IMPORT":return "导入完成，重复联系人保留原资格、拒绝与历史。";case "PLAN":return "已安排单次自动模拟；到时将检查最新规则。";case "AUTO_30":return "已安排30秒后单次自动模拟，不拨电话。";case "IMMEDIATE":case "EXECUTE":return "模拟请求已记录，请核对模拟结果；没有真实电话。";case "PAUSE":return "计划已暂停，后续需明确重新安排。";case "RESULT_UNKNOWN":return "结果仍未知，占用保留；不得自动重放。";case "CLOSE_UNKNOWN":return "已明确关闭旧占用，历史结果仍未知。";default:return "状态已更新。";}}
 private static String human(String code){if(code==null)return "操作未完成，请刷新核对状态。";if(code.startsWith("INVALID_LINE_"))return "第"+code.substring(13)+"行无效：只接受SIM-三位数字。整批未导入。";switch(code){case "EXACT_ALARM_REQUIRED":return "请先在系统设置允许此仿真应用的闹钟和提醒权限。";case "BACKGROUND_RESTRICTED":return "请先允许此仿真应用后台运行。";case "TOO_MANY_LINES":return "每批最多200行，整批未导入。";case "INPUT_TOO_LARGE":return "输入超过8000字符，整批未导入。";case "INVALID_BEIJING_TIME":return "时间格式无效，请用北京时间 yyyy-MM-dd HH:mm。";case "PAST_DUE":return "时间已经过去，请重新安排未来时间。";case "OUTSIDE_WINDOW":return "需在北京时间周一至周五09:00–18:00内模拟执行。";case "NOT_DUE":return "计划尚未到时，不会提前模拟提交。";case "EXPIRED":return "计划已超出30秒执行窗口，已暂停，请重新安排。";case "OCCUPIED":return "仍有待核对尝试，请先处理结果，不会重复提交。";case "STALE_PLAN":return "计划版本已变化，请刷新后重新操作。";case "STALE_CONTACT":case "STALE_DRAFT":return "联系人或草稿已变化，请明确刷新所选草稿后重排。";case "DO_NOT_CONTACT":return "联系人已拒绝联系，不能安排或再次尝试。";case "CONTACT_NOT_QUALIFIED":return "合成资格未确认，不能安排。";case "SELECT_CONTACT":return "请先导入并选择合成联系人。";default:return "操作未完成，请刷新核对状态；不会自动重试。";}}
 @Override protected void onResume(){super.onResume();WorkspaceTimerRuntime.visible=true;WorkspaceTimerRuntime.listener=()->runOnUiThread(()->{if(!busy&&current!=null&&!isFinishing()&&!isDestroyed())submit("TIMER_REFRESH",(v,r)->{});});if(!busy&&current!=null)submit("TIMER_REFRESH",(v,r)->{});}
 @Override protected void onPause(){WorkspaceTimerRuntime.visible=false;WorkspaceTimerRuntime.listener=null;super.onPause();}
 @Override protected void onSaveInstanceState(Bundle saved){saved.putString("selected",selectedId);super.onSaveInstanceState(saved);}
 @Override protected void onDestroy(){worker.execute(()->{synchronized(WorkspaceTimerCoordinator.LOCK){if(session!=null)session.close();}});worker.shutdown();super.onDestroy();}
}
